<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();$pdo=db();$message=flash('success');$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$sql=file_get_contents(__DIR__.'/upgrade_phase6.sql');$sql=preg_replace('/^\s*USE\s+`[^`]+`\s*;\s*/i','',$sql,1);foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql) as $s){$s=trim($s);if($s!=='')$pdo->exec($s);}activity($pdo,'upgrade','system',null,'Phase 6 database upgrade applied');flash('success','Phase 6 database upgrade completed successfully.');redirect('upgrade_phase6.php');}catch(Throwable $e){error_log('[SPS PHASE 6] '.$e->getMessage());$error='Phase 6 could not be installed. Verify Phase 5 is installed and MySQL is running.';}}
$ready=true;foreach(['password_resets','login_attempts','communication_templates','approvals','exceptions','workflow_checkpoints'] as $t){if(!table_exists($pdo,$t)){$ready=false;break;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 6 Setup</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.box{max-width:760px;margin:60px auto;background:#fff;border:1px solid #e4e9f1;border-radius:18px;padding:30px}.note{background:#f4f7ff;padding:14px;border-radius:10px}.ok{color:#16804a;font-weight:800}.bad{color:#a22f2f;font-weight:800}.btn{background:#315ee7;color:#fff;border:0;padding:12px 16px;border-radius:9px;font-weight:800}</style></head><body><div class="box"><h1>Phase 6 Database Setup</h1><p class="note">Additive migration only; previous CRM data is not intentionally reset.</p><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif;?><?php if($error):?><p class="bad"><?=e($error)?></p><?php endif;?><p>Status: <b class="<?= $ready?'ok':'bad'?>"><?=$ready?'READY':'UPGRADE REQUIRED'?></b></p><?php if(!$ready):?><form method="post"><?=csrf_field()?><button class="btn">Apply Phase 6 Database Upgrade</button></form><?php endif;?></div></body></html>
